import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_bias_add_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Kernel for adding bias across each channel of an NCHW tensor
__global__ void bias_add_kernel(const float* input, const float* bias, float* output,
                                int batch_size, int channels, int height, int width) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = batch_size * channels * height * width;
    if (idx < total_size) {
        // Compute the index for each dimension
        int w = idx % width;
        int tmp = idx / width;
        int h = tmp % height;
        tmp /= height;
        int c = tmp % channels;
        int b = tmp / channels;

        int bias_idx = c;
        int input_idx = ((b * channels + c) * height + h) * width + w;
        output[input_idx] = input[input_idx] + bias[bias_idx];
    }
}

torch::Tensor fused_bias_add_cuda(torch::Tensor input, torch::Tensor bias) {
    auto batch_size = input.size(0);
    auto channels   = input.size(1);
    auto height     = input.size(2);
    auto width      = input.size(3);

    auto output = torch::zeros_like(input);

    int total_size = batch_size * channels * height * width;
    int block_size = 256;
    int grid_size = (total_size + block_size - 1) / block_size;

    bias_add_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        height,
        width
    );

    return output;
}
""".strip()

fused_bias_add_cpp_source = r"""
torch::Tensor fused_bias_add_cuda(torch::Tensor input, torch::Tensor bias);
"""

fused_bias_add = load_inline(
    name="fused_bias_add",
    cpp_sources=fused_bias_add_cpp_source,
    cuda_sources=fused_bias_add_source,
    functions=["fused_bias_add_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized version of a transposed 2D convolution with optional custom CUDA bias addition.
    """
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: int = 1,
        padding: int = 0,
        output_padding: int = 0,
        groups: int = 1,
        bias: bool = False
    ):
        super(ModelNew, self).__init__()
        # Use PyTorch's ConvTranspose2d without bias
        self.conv_transpose2d = nn.ConvTranspose2d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding,
            output_padding=output_padding, groups=groups, bias=False
        )
        self.use_bias = bias
        if self.use_bias:
            # Create a learnable bias parameter separately
            self.bias_param = nn.Parameter(torch.zeros(out_channels))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        out = self.conv_transpose2d(x)
        # If bias is used, apply our custom CUDA bias addition
        if self.use_bias:
            out = fused_bias_add.fused_bias_add_cuda(out, self.bias_param)
        return out
